// Refresh the local-file fallback after editing either doctrine JSON file.
const fs = require('node:fs');
const path = require('node:path');

const read = name => JSON.parse(fs.readFileSync(path.join(__dirname, name), 'utf8').replace(/^\uFEFF/, ''));
function update() {
    const data = {
        chart: read('doctrine-compare.json'),
        perks: read('perk-assets.json'),
    };
    fs.writeFileSync(path.join(__dirname, 'doctrine-local.js'),
        '// Generated by node data/update-doctrine-local.cjs; edit the JSON sources.\n' +
        `window.doctrineLocalData = ${JSON.stringify(data, null, 2)};\n`);
}

update();

if (process.argv.includes('--watch')) {
    let pending;
    fs.watch(__dirname, (_, filename) => {
        if (!['doctrine-compare.json', 'perk-assets.json'].includes(String(filename))) return;
        clearTimeout(pending);
        pending = setTimeout(() => {
            try {
                update();
            } catch (error) {
                // Keep the last valid data while an edit contains incomplete JSON.
                console.error(`Doctrine data was not updated: ${error.message}`);
            }
        }, 150);
    });
    console.log('Watching doctrine JSON files. Reload the chart after saving.');
}
